// Query Redis for pending upload jobs
const redis = require('redis');
const { getRedisClient } = require('/workspace/002-n8n/lib/redis-client');

const redisClient = getRedisClient();

// Connect if not already connected
const connectResult = await redisClient.connect();

if (!connectResult.success) {
  console.log('Redis unavailable, skipping poll cycle');
  return [];
}

// Get all pending jobs from sorted set
// ZRANGE returns jobs sorted by timestamp (score)
const result = await redisClient.execute(
  async (client) => {
    // Get jobs with status 'processing' (up to 50 at a time)
    return await client.zRange('upload_jobs:pending', 0, 49, {
      REV: false // oldest first
    });
  },
  [] // fallback to empty array
);

if (!result.success || result.data.length === 0) {
  console.log(`No pending jobs found (stateless: ${result.stateless})`);
  return [];
}

const jobIds = result.data;
console.log(`Found ${jobIds.length} pending upload jobs`);

// Fetch job details from Redis
const jobs = [];
for (const jobId of jobIds) {
  const jobResult = await redisClient.execute(
    async (client) => {
      const jobData = await client.get(`upload_job:${jobId}`);
      return jobData ? JSON.parse(jobData) : null;
    },
    null
  );

  if (jobResult.success && jobResult.data) {
    jobs.push({
      job_id: jobId,
      ...jobResult.data
    });
  }
}

return jobs.map(job => ({ json: job }));

// Format completion notification for MS Teams
const jobData = $input.first().json;
const status = jobData.status;
const jobId = jobData.job_id || $json.job_id;
const fileName = jobData.file_name || jobData.document_name || 'document';
const documentId = jobData.document_id;

let message = '';
let conversationId = jobData.conversation_id;
let userId = jobData.user_id;

if (status === 'completed') {
  message = `✅ **Document Upload Complete**\n\n`;
  message += `📄 **File:** ${fileName}\n`;
  message += `🆔 **Document ID:** ${documentId}\n\n`;
  message += `Your document has been successfully processed and indexed. `;
  message += `You can now search for information from this document using natural language queries.\n\n`;
  message += `*Powered by BMS Agent*`;
} else if (status === 'failed') {
  message = `❌ **Document Upload Failed**\n\n`;
  message += `📄 **File:** ${fileName}\n`;
  message += `⚠️ **Error:** ${jobData.error || 'Unknown error occurred during processing'}\n\n`;
  message += `Please try uploading the document again. If the problem persists, contact support.\n\n`;
  message += `*Powered by BMS Agent*`;
}

return {
  json: {
    message,
    conversationId,
    userId,
    jobId,
    status,
    fileName,
    documentId: documentId || null
  }
};

// Remove completed/failed job from Redis
const { getRedisClient } = require('/workspace/002-n8n/lib/redis-client');
const redisClient = getRedisClient();

const jobId = $json.jobId;
const status = $json.status;

console.log(`Removing job ${jobId} with status ${status} from pending queue`);

// Remove from sorted set
await redisClient.execute(
  async (client) => {
    // Remove from pending queue
    await client.zRem('upload_jobs:pending', jobId);

    // Update job record with final status
    const jobKey = `upload_job:${jobId}`;
    const jobData = await client.get(jobKey);

    if (jobData) {
      const job = JSON.parse(jobData);
      job.status = status;
      job.completed_at = new Date().toISOString();

      // Store with 7-day TTL for audit trail
      await client.setEx(jobKey, 7 * 24 * 60 * 60, JSON.stringify(job));
    }

    return true;
  },
  false
);

console.log(`✓ Job ${jobId} cleanup complete`);

return {
  json: {
    jobId,
    status,
    action: 'removed_from_queue',
    timestamp: new Date().toISOString()
  }
};

// Log processing summary
const items = $input.all();

if (items.length === 0) {
  console.log('✓ Poll cycle complete - no pending jobs');
  return [{ json: { status: 'no_jobs', timestamp: new Date().toISOString() } }];
}

const completed = items.filter(item => item.json.status === 'completed').length;
const failed = items.filter(item => item.json.status === 'failed').length;
const processing = items.filter(item => item.json.status === 'processing').length;

console.log(`✓ Poll cycle complete:`);
console.log(`  - Completed: ${completed}`);
console.log(`  - Failed: ${failed}`);
console.log(`  - Still processing: ${processing}`);

return [{
  json: {
    status: 'cycle_complete',
    completed,
    failed,
    processing,
    timestamp: new Date().toISOString()
  }
}];
